def _cov_query(c, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(c, p, buf, cap)
    if n < 0:
        raise AraelError(
            n, (_f.graph_cov_error(c) or b"").decode())
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """An assembled covariance, OWNED: released on garbage
    collection (free() to force it), independent of later assemblies.
    Per-entity queries (marginal/conditional by param count: 1 ->
    float, 2/3 -> matrix2d/3d, larger -> row-major tuples). Entity
    arguments must come from the live model."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def plan(self):
        """What the assembly decided -- the ordering it kept, what the
        candidates priced at, and how many symbolics it built."""
        p = CovPlan()
        _f.graph_cov_plan(self._h, ctypes.byref(p))
        return p

    def free(self):
        if self._h:
            _f.graph_cov_free(self._h)
            self._h = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, Pose2):
            return (_shape_3)(_cov_query(self._h, _f.graph_pose2_marginal_cov, e._p, 9))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, Pose2):
            return (_shape_3)(_cov_query(self._h, _f.graph_pose2_conditional_cov, e._p, 9))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, Pose2):
            return list(_cov_query(self._h, _f.graph_pose2_std_dev, e._p, 3))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_pose2_pose2(self, a, b):
        buf = (ctypes.c_double * 9)()
        rows = _f.graph_pose2_pose2_cross_cov(self._h, a._p, b._p, buf, 9)
        if rows < 0:
            raise AraelError(
                rows, (_f.graph_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, Pose2) and isinstance(b, Pose2):
            return self._cross_pose2_pose2(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class GraphPosesVec:
    """View of `poses` (vec of Pose2); element wrappers re-resolve
    their pointer by key on every access, so growing the collection
    cannot leave them dangling. Mutating while iterating is undefined.

    Construction and bulk edits cross the FFI once per call: push(**fields)
    fills the new element's fields in the same call as the push;
    push_many(**arrays) appends many; set_<field>(values) / get_<field>()
    move one column of the whole collection."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.graph_poses_len(self._p)

    def reserve(self, additional):
        _f.graph_poses_reserve(self._p, additional)

    def __getitem__(self, i):
        if isinstance(i, Pose2Ref):
            return Pose2(lambda r=i.raw: _f.graph_poses_get(self._p, r), i)
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Pose2(lambda i=i: _f.graph_poses_at(self._p, i), i)

    def __iter__(self):
        for i in range(len(self)):
            yield Pose2(lambda i=i: _f.graph_poses_at(self._p, i), i)

    def clear(self):
        _f.graph_poses_clear(self._p)

    def truncate(self, n):
        _f.graph_poses_truncate(self._p, n)

    def push(self, *, pos=None, pos_optimize=None, rot_angle=None,
                 rot_angle_optimize=None):
        """Appends one element and returns it; each keyword sets that
        field in the same call, an omitted one keeps the Rust default."""
        m = 0
        if pos is None: pos = _Z2
        else:
            m |= 1 << 0; pos = tuple(pos)
            if len(pos) != 2: pos = _cols.flat(pos, 2)
        if pos_optimize is None: pos_optimize = 0
        else: m |= 1 << 1; pos_optimize = 1 if pos_optimize else 0
        if rot_angle is None: rot_angle = 0.0
        else: m |= 1 << 2
        if rot_angle_optimize is None: rot_angle_optimize = 0
        else: m |= 1 << 3; rot_angle_optimize = 1 if rot_angle_optimize else 0
        _pose2_rec.pack_into(_pose2_slots, 0,
            m, *pos, pos_optimize, rot_angle, rot_angle_optimize)
        r = Pose2Ref(_f.graph_poses_push_n(self._p, _pose2_slots, 1))
        return Pose2(lambda k=r.raw: _f.graph_poses_get(self._p, k), r)

    def pop(self):
        """Drops the last element; False when already empty."""
        return _f.graph_poses_pop(self._p)

    def push_many(self, n=None, *, pos=None, pos_optimize=None, rot_angle=None,
                  rot_angle_optimize=None):
        """Appends `n` elements in one call. Each keyword is one value
        for all of them or a sequence with one per element (a numpy
        array of the matching dtype is read in place); `n` may be
        omitted when some keyword is a sequence. Returns the index of
        the first new element."""
        n = _cols.count(n, (("pos", pos), ("pos_optimize", pos_optimize),
                        ("rot_angle", rot_angle),
                        ("rot_angle_optimize", rot_angle_optimize)))
        i0 = len(self)
        _f.graph_poses_push_n(self._p, None, n)
        if pos is not None:
            self._set_pos(i0, n, pos)
        if pos_optimize is not None:
            self._set_pos_optimize(i0, n, pos_optimize)
        if rot_angle is not None:
            self._set_rot_angle(i0, n, rot_angle)
        if rot_angle_optimize is not None:
            self._set_rot_angle_optimize(i0, n, rot_angle_optimize)
